def box(x,y,w,h,c,t='',sz=14,tc=WHITE,r=8): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}"/>'+(text(x+w/2,y+h/2+sz*0.36,t,sz,tc) if t else '')
def clock(x,y,r,h,m):
    a=lambda v,l:(x+l*math.sin(v),y-l*math.cos(v))
    hx,hy=a((h%12+m/60)*math.pi/6,r*0.5); mx,my=a(m*math.pi/30,r*0.8)
    return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{WHITE}" stroke="{BLUE}" stroke-width="4"/>'+''.join(f'<line x1="{x+(r-6)*math.sin(i*math.pi/6):.1f}" y1="{y-(r-6)*math.cos(i*math.pi/6):.1f}" x2="{x+(r-1)*math.sin(i*math.pi/6):.1f}" y2="{y-(r-1)*math.cos(i*math.pi/6):.1f}" stroke="{INK}" stroke-width="2"/>' for i in range(12))+f'<line x1="{x}" y1="{y}" x2="{hx:.1f}" y2="{hy:.1f}" stroke="{INK}" stroke-width="4"/><line x1="{x}" y1="{y}" x2="{mx:.1f}" y2="{my:.1f}" stroke="{INK}" stroke-width="3"/>'
def face(x,y,s=1,c=SKIN,hair=BROWN,sad=False):
    m=f'<path d="M-6 8 q6 -6 12 0" stroke="#000" stroke-width="2" fill="none"/>' if sad else f'<path d="M-6 5 q6 6 12 0" stroke="#000" stroke-width="2" fill="none"/>'
    return f'<g transform="translate({x} {y}) scale({s})"><circle r="16" fill="{c}"/><path d="M-16 -4 q16 -24 32 0 Z" fill="{hair}"/><circle cx="-5" cy="-2" r="2" fill="#000"/><circle cx="5" cy="-2" r="2" fill="#000"/>{m}</g>'
def bldg(x,y,w,h,c,t=''): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{c}"/>'+''.join(f'<rect x="{x+6+i*16}" y="{y+8+j*18}" width="9" height="11" fill="{LBLUE}"/>' for i in range(int((w-6)//16)) for j in range(max(0,int((h-30)//18))))+(text(x+w/2,y+h-8,t,9,WHITE) if t else '')
def bear(x,y,s=1,c=BROWN): return f'<g transform="translate({x} {y}) scale({s})"><circle cx="-16" cy="-16" r="8" fill="{c}"/><circle cx="16" cy="-16" r="8" fill="{c}"/><circle r="20" fill="{c}"/><ellipse cy="6" rx="9" ry="7" fill="{SAND}"/><circle cx="-7" cy="-4" r="2.5" fill="#000"/><circle cx="7" cy="-4" r="2.5" fill="#000"/><circle cy="3" r="3" fill="#000"/></g>'
def fish(x,y,s=1,c=ORANGE): return f'<g transform="translate({x} {y}) scale({s})"><ellipse rx="22" ry="12" fill="{c}"/><polygon points="20,0 36,-12 36,12" fill="{c}"/><circle cx="-10" cy="-3" r="2.5" fill="#000"/></g>'
def wing_bird(x,y,s=1,c=RED): return f'<g transform="translate({x} {y}) scale({s})"><ellipse rx="22" ry="12" fill="{c}"/><circle cx="20" cy="-6" r="9" fill="{c}"/><polygon points="28,-6 38,-3 28,0" fill="{YEL}"/><path d="M-6 -2 q-10 -28 14 -26" fill="{BLUE}"/><circle cx="23" cy="-8" r="2" fill="#000"/></g>'
def shirt(x,y,c=BLUE): return f'<path d="M{x-22} {y} l14 -10 q8 8 16 0 l14 10 l-8 12 l-6 -4 v28 h-26 v-28 l-6 4 Z" fill="{c}"/>'
def mtn(): return f'<polygon points="0,170 70,70 130,150 190,60 260,150 320,90 320,170" fill="{DGREEN}"/>'
